// Maps the raw Kindwise Crop Health response into the CropDiagnosisResult
// contract (packages/shared-types). Shape verified against
// flowerchecker/kindwise-api-client (the vendor's own reference client):
// result = { is_plant: {probability,binary,threshold}, crop: {suggestions:[...]}, disease: {suggestions:[...]} }.
// There is NO is_healthy field — the API gives no positive health score,
// only disease-candidate probabilities, so "healthy" below is reported
// as "no significant disease signal" rather than a guaranteed clean
// bill of health. Every field here comes from the API's own reported
// values — nothing is invented, and a low-confidence/unrecognized
// result becomes "inconclusive" rather than a forced diagnosis.
const NOT_A_PLANT_THRESHOLD = 0.5;
const HIGH_THRESHOLD = 0.75;
const MEDIUM_THRESHOLD = 0.4;
const MIN_USABLE_THRESHOLD = 0.2;

const body = $input.first().json.body ?? $input.first().json;
const result = body?.result ?? {};
const isPlant = result.is_plant?.probability ?? null;
const suggestions = result.disease?.suggestions ?? [];
const top = suggestions[0] ?? null;

let primaryFinding;
let recommendExpertConsult = false;
let expertConsultReason = null;

if (isPlant !== null && isPlant < NOT_A_PLANT_THRESHOLD) {
  primaryFinding = { label: "Inconclusive", category: "inconclusive", confidence: isPlant };
  recommendExpertConsult = true;
  expertConsultReason = "The model isn't confident this photo clearly shows a plant/crop.";
} else if (!top || top.probability < MIN_USABLE_THRESHOLD) {
  primaryFinding = { label: "No significant disease detected", category: "healthy", confidence: top?.probability ?? 0 };
} else {
  primaryFinding = { label: top.name, category: "disease", confidence: top.probability };
  if (top.probability < MEDIUM_THRESHOLD) {
    recommendExpertConsult = true;
    expertConsultReason = "Model confidence is low — verify with a local expert before acting.";
  }
}

const confidenceLevel =
  primaryFinding.category === "healthy"
    ? primaryFinding.confidence < 0.1 ? "high" : "medium"
    : primaryFinding.confidence >= HIGH_THRESHOLD
      ? "high"
      : primaryFinding.confidence >= MEDIUM_THRESHOLD
        ? "medium"
        : "low";

const alternativePossibilities = suggestions.slice(1, 4).map((s) => ({
  label: s.name,
  category: "disease",
  confidence: s.probability
}));

const visualEvidence = (top?.similar_images ?? []).slice(0, 4).map((img) => ({
  referenceImageUrl: img.url,
  matchScore: img.similarity ?? 0
}));

// Non-chemical guidance sourced directly from Kindwise's own 'treatment'
// detail (requested above): only the 'prevention' and 'biological'
// sub-keys are ever read here — 'chemical' is deliberately never
// touched, so a pesticide/chemical recommendation cannot reach the
// frontend even if Kindwise's own data includes one.
const toList = (v) => (Array.isArray(v) ? v.map(String) : v ? [String(v)] : []);
const treatment = top?.details?.treatment ?? {};
const culturalPractices = [...toList(treatment.prevention), ...toList(treatment.biological)];

const monitoring = [];
if (top?.details?.symptoms) monitoring.push(`Watch for: ${top.details.symptoms}`);
if (top?.details?.spreading) monitoring.push(`Spreads via: ${top.details.spreading}`);

if (primaryFinding.category === "disease" && culturalPractices.length === 0) {
  recommendExpertConsult = true;
  expertConsultReason = expertConsultReason ?? "No vetted non-chemical guidance is available from the data source for this specific finding.";
}

return [
  {
    json: {
      status: "ok",
      asOf: new Date().toISOString(),
      source: "kindwise-crop-health",
      data: {
        cropName: $('Core Trigger').first().json.cropName ?? null,
        primaryFinding,
        alternativePossibilities,
        visualEvidence,
        confidenceLevel,
        careGuidance: { culturalPractices, monitoring },
        recommendExpertConsult,
        expertConsultReason,
        disclaimer:
          "This is an automated visual estimate, not a lab diagnosis. Confirm with a qualified local agricultural expert before taking any action, especially before applying any treatment.",
        modelInfo: { provider: "kindwise-crop-health", ranAt: new Date().toISOString() }
      }
    }
  }
];
